     1→// FreeLang v4 — Parser (SPEC_05 구현)
     2→// RD(문) + Pratt(식) 하이브리드
     3→
     4→import { Token, TokenType } from "./lexer";
     5→import {
     6→  Program, Stmt, Expr, TypeAnnotation, Pattern, MatchArm, Param, StructField, FnParam,
     7→} from "./ast";
     8→
     9→// ============================================================
    10→// ParseError
    11→// ============================================================
    12→
    13→export type ParseError = {
    14→  message: string;
    15→  line: number;
    16→  col: number;
    17→};
    18→
    19→// ============================================================
    20→// Binding Power (SPEC_05 Q4)
    21→// ============================================================
    22→
    23→const BP_ASSIGN = 10;
    24→const BP_OR = 20;
    25→const BP_AND = 30;
    26→const BP_EQUALITY = 40;
    27→const BP_COMPARISON = 50;
    28→const BP_ADDITIVE = 60;
    29→const BP_MULTIPLICATIVE = 70;
    30→const BP_UNARY = 90;
    31→const BP_POSTFIX = 100;
    32→
    33→function infixBP(type: TokenType): number {
    34→  switch (type) {
    35→    // EQ는 Pratt에서 처리하지 않음 → ExprStmt에서 할당으로 처리
    36→    case TokenType.OR: return BP_OR;
    37→    case TokenType.AND: return BP_AND;
    38→    case TokenType.EQEQ:
    39→    case TokenType.NEQ: return BP_EQUALITY;
    40→    case TokenType.LT:
    41→    case TokenType.GT:
    42→    case TokenType.LTEQ:
    43→    case TokenType.GTEQ: return BP_COMPARISON;
    44→    case TokenType.PLUS:
    45→    case TokenType.MINUS: return BP_ADDITIVE;
    46→    case TokenType.STAR:
    47→    case TokenType.SLASH:
    48→    case TokenType.PERCENT: return BP_MULTIPLICATIVE;
    49→    case TokenType.LPAREN:
    50→    case TokenType.LBRACKET:
    51→    case TokenType.DOT:
    52→    case TokenType.QUESTION: return BP_POSTFIX;
    53→    default: return 0;
    54→  }
    55→}
    56→
    57→// ============================================================
    58→// Parser
    59→// ============================================================
    60→
    61→export class Parser {
    62→  private tokens: Token[];
    63→  private pos: number = 0;
    64→  private errors: ParseError[] = [];
    65→
    66→  constructor(tokens: Token[]) {
    67→    this.tokens = tokens;
    68→  }
    69→
    70→  parse(): { program: Program; errors: ParseError[] } {
    71→    const stmts: Stmt[] = [];
    72→    while (!this.isAtEnd()) {
    73→      try {
    74→        stmts.push(this.parseStmt());
    75→      } catch (e) {
    76→        // 에러 복구: 다음 문 시작까지 건너뜀
    77→        this.synchronize();
    78→      }
    79→    }
    80→    return { program: { stmts }, errors: this.errors };
    81→  }
    82→
    83→  // ============================================================
    84→  // 문 파싱 — Recursive Descent (SPEC_05 Q1)
    85→  // ============================================================
    86→
    87→  private parseStmt(): Stmt {
    88→    const tok = this.peek();
    89→
    90→    switch (tok.type) {
    91→      case TokenType.VAR:
    92→      case TokenType.LET:
    93→      case TokenType.CONST:
    94→        return this.parseVarDecl();
    95→      case TokenType.FN:
    96→        return this.parseFnDecl();
    97→      case TokenType.STRUCT:
    98→        return this.parseStructDecl();
    99→      case TokenType.IF:
   100→        return this.parseIfStmt();
   101→      case TokenType.MATCH:
   102→        return this.parseMatchStmt();
   103→      case TokenType.FOR:
   104→        return this.parseForStmt();
   105→      case TokenType.WHILE:
   106→        return this.parseWhileStmt();
   107→      case TokenType.BREAK:
   108→        return this.parseBreakStmt();
   109→      case TokenType.CONTINUE:
   110→        return this.parseContinueStmt();
   111→      case TokenType.SPAWN:
   112→        return this.parseSpawnStmt();
   113→      case TokenType.RETURN:
   114→        return this.parseReturnStmt();
   115→      default:
   116→        return this.parseExprStmt();
   117→    }
   118→  }
   119→
   120→  // var/let/const 선언
   121→  private parseVarDecl(): Stmt {
   122→    const kw = this.advance(); // var/let/const
   123→    const mutable = kw.type === TokenType.VAR;
   124→    const name = this.expectIdent("variable name");
   125→    let type: TypeAnnotation | null = null;
   126→
   127→    if (this.check(TokenType.COLON)) {
   128→      this.advance(); // :
   129→      type = this.parseType();
   130→    }
   131→
   132→    this.expect(TokenType.EQ, "expected '=' in variable declaration");
   133→    const init = this.parseExpr(0);
   134→    this.match(TokenType.SEMICOLON); // optional semicolon
   135→
   136→    return { kind: "var_decl", name, mutable, type, init, line: kw.line, col: kw.col };
   137→  }
   138→
   139→  // fn 선언
   140→  private parseFnDecl(): Stmt {
   141→    const kw = this.advance(); // fn
   142→    const name = this.expectIdent("function name");
   143→
   144→    // Generic 타입 파라미터: fn foo<T, K>(...) [STEP B-1]
   145→    const typeParams: string[] = [];
   146→    if (this.match(TokenType.LT)) {
   147→      do {
   148→        typeParams.push(this.expectIdent("type parameter"));
   149→      } while (this.match(TokenType.COMMA));
   150→      this.expect(TokenType.GT, "expected '>' after type parameters");
   151→    }
   152→
   153→    this.expect(TokenType.LPAREN, "expected '(' after function name");
   154→
   155→    const params: Param[] = [];
   156→    if (!this.check(TokenType.RPAREN)) {
   157→      do {
   158→        const pName = this.expectIdent("parameter name");
   159→        this.expect(TokenType.COLON, "expected ':' after parameter name");
   160→        const pType = this.parseType();
   161→        params.push({ name: pName, type: pType });
   162→      } while (this.match(TokenType.COMMA));
   163→    }
   164→    this.expect(TokenType.RPAREN, "expected ')' after parameters");
   165→
   166→    // 반환 타입 (필수 — SPEC_06: 함수 시그니처 명시)
   167→    this.expect(TokenType.RARROW, "expected '->' for return type");
   168→    const returnType = this.parseType();
   169→
   170→    this.expect(TokenType.LBRACE, "expected '{' for function body");
   171→    const body = this.parseBlock();
   172→
   173→    return { kind: "fn_decl", name, typeParams, params, returnType, body, line: kw.line, col: kw.col };
   174→  }
   175→
   176→  // struct 선언
   177→  private parseStructDecl(): Stmt {
   178→    const kw = this.advance(); // struct
   179→    const name = this.expectIdent("struct name");
   180→
   181→    // Generic 타입 파라미터: struct Box<T> [STEP B-2]
   182→    const typeParams: string[] = [];
   183→    if (this.match(TokenType.LT)) {
   184→      do {
   185→        typeParams.push(this.expectIdent("type parameter"));
   186→      } while (this.match(TokenType.COMMA));
   187→      this.expect(TokenType.GT, "expected '>' after type parameters");
   188→    }
   189→
   190→    this.expect(TokenType.LBRACE, "expected '{' after struct name");
   191→
   192→    const fields: StructField[] = [];
   193→    if (!this.check(TokenType.RBRACE)) {
   194→      do {
   195→        const fieldName = this.expectIdent("field name");
   196→        this.expect(TokenType.COLON, "expected ':' after field name");
   197→        const fieldType = this.parseType();
   198→        fields.push({ name: fieldName, type: fieldType });
   199→      } while (this.match(TokenType.COMMA));
   200→    }
   201→
   202→    this.expect(TokenType.RBRACE, "expected '}' to close struct");
   203→
   204→    return { kind: "struct_decl", name, typeParams, fields, line: kw.line, col: kw.col };
   205→  }
   206→
   207→  // if 문 (문 위치)
   208→  private parseIfStmt(): Stmt {
   209→    const kw = this.advance(); // if
   210→    const condition = this.parseExpr(0);
   211→    this.expect(TokenType.LBRACE, "expected '{' after if condition");
   212→    const then = this.parseBlock();
   213→
   214→    let else_: Stmt[] | null = null;
   215→    if (this.match(TokenType.ELSE)) {
   216→      if (this.check(TokenType.IF)) {
   217→        // else if 체인
   218→        else_ = [this.parseIfStmt()];
   219→      } else {
   220→        this.expect(TokenType.LBRACE, "expected '{' after else");
   221→        else_ = this.parseBlock();
   222→      }
   223→    }
   224→
   225→    return { kind: "if_stmt", condition, then, else_, line: kw.line, col: kw.col };
   226→  }
   227→
   228→  // match 문
   229→  private parseMatchStmt(): Stmt {
   230→    const kw = this.advance(); // match
   231→    const subject = this.parseExpr(0);
   232→    this.expect(TokenType.LBRACE, "expected '{' after match expression");
   233→    const arms = this.parseMatchArms();
   234→    this.expect(TokenType.RBRACE, "expected '}' to close match");
   235→
   236→    return { kind: "match_stmt", subject, arms, line: kw.line, col: kw.col };
   237→  }
   238→
   239→  // for 문
   240→  private parseForStmt(): Stmt {
   241→    const kw = this.advance(); // for
   242→    const variable = this.expectIdent("loop variable");
   243→
   244→    // for...in or for...of
   245→    const loopType = this.peek().type;
   246→    if (loopType === TokenType.IN) {
   247→      this.advance(); // in
   248→      const iterable = this.parseExpr(0);
   249→      this.expect(TokenType.LBRACE, "expected '{' after for...in");
   250→      const body = this.parseBlock();
   251→      return { kind: "for_stmt", variable, iterable, body, line: kw.line, col: kw.col };
   252→    } else if (loopType === TokenType.OF) {
   253→      this.advance(); // of
   254→      const iterable = this.parseExpr(0);
   255→      this.expect(TokenType.LBRACE, "expected '{' after for...of");
   256→      const body = this.parseBlock();
   257→      return { kind: "for_of_stmt", variable, iterable, body, line: kw.line, col: kw.col };
   258→    } else {
   259→      this.error("expected 'in' or 'of' after loop variable", this.peek());
   260→      return { kind: "for_stmt", variable, iterable: { kind: "ident", name: "", line: kw.line, col: kw.col }, body: [], line: kw.line, col: kw.col };
   261→    }
   262→  }
   263→
   264→  // while 문
   265→  private parseWhileStmt(): Stmt {
   266→    const kw = this.advance(); // while
   267→    const condition = this.parseExpr(0);
   268→    this.expect(TokenType.LBRACE, "expected '{' after while condition");
   269→    const body = this.parseBlock();
   270→
   271→    return { kind: "while_stmt", condition, body, line: kw.line, col: kw.col };
   272→  }
   273→
   274→  // break 문
   275→  private parseBreakStmt(): Stmt {
   276→    const kw = this.advance(); // break
   277→    this.match(TokenType.SEMICOLON); // optional semicolon
   278→    return { kind: "break_stmt", line: kw.line, col: kw.col };
   279→  }
   280→
   281→  // continue 문
   282→  private parseContinueStmt(): Stmt {
   283→    const kw = this.advance(); // continue
   284→    this.match(TokenType.SEMICOLON); // optional semicolon
   285→    return { kind: "continue_stmt", line: kw.line, col: kw.col };
   286→  }
   287→
   288→  // spawn 문
   289→  private parseSpawnStmt(): Stmt {
   290→    const kw = this.advance(); // spawn
   291→    this.expect(TokenType.LBRACE, "expected '{' after spawn");
   292→    const body = this.parseBlock();
   293→
   294→    return { kind: "spawn_stmt", body, line: kw.line, col: kw.col };
   295→  }
   296→
   297→  // return 문
   298→  private parseReturnStmt(): Stmt {
   299→    const kw = this.advance(); // return
   300→
   301→    // return 뒤에 식이 있는지 확인
   302→    let value: Expr | null = null;
   303→    if (!this.check(TokenType.RBRACE) && !this.isAtEnd() && !this.isStmtStart()) {
   304→      value = this.parseExpr(0);
   305→    }
   306→    this.match(TokenType.SEMICOLON); // optional semicolon
   307→
   308→    return { kind: "return_stmt", value, line: kw.line, col: kw.col };
   309→  }
   310→
   311→  // 식 문 (ExprStmt)
   312→  private parseExprStmt(): Stmt {
   313→    const tok = this.peek();
   314→    const expr = this.parseExpr(0);
   315→
   316→    // 할당 처리: expr = value
   317→    if (this.check(TokenType.EQ)) {
   318→      const eq = this.advance();
   319→      const value = this.parseExpr(0);
   320→      this.match(TokenType.SEMICOLON); // optional semicolon
   321→      return {
   322→        kind: "expr_stmt",
   323→        expr: { kind: "assign", target: expr, value, line: eq.line, col: eq.col },
   324→        line: tok.line,
   325→        col: tok.col,
   326→      };
   327→    }
   328→
   329→    this.match(TokenType.SEMICOLON); // optional semicolon
   330→    return { kind: "expr_stmt", expr, line: tok.line, col: tok.col };
   331→  }
   332→
   333→  // ============================================================
   334→  // 블록 파싱 ({ 이미 소비됨, } 소비함 )
   335→  // ============================================================
   336→
   337→  private parseBlock(): Stmt[] {
   338→    const stmts: Stmt[] = [];
   339→    while (!this.check(TokenType.RBRACE) && !this.isAtEnd()) {
   340→      try {
   341→        stmts.push(this.parseStmt());
   342→      } catch {
   343→        this.synchronize();
   344→      }
   345→    }
   346→    this.expect(TokenType.RBRACE, "expected '}'");
   347→    return stmts;
   348→  }
   349→
   350→  // ============================================================
   351→  // 식 파싱 — Pratt Parser (SPEC_05 Q3, Q4)
   352→  // ============================================================
   353→
   354→  private parseExpr(minBP: number): Expr {
   355→    let left = this.nud();
   356→
   357→    while (!this.isAtEnd()) {
   358→      const tok = this.peek();
   359→
   360→      // 구조체 리터럴: ident { field: value, ... }
   361→      // Lookahead: { 다음이 ident: 패턴인지 확인 (while/if 블록과 구분)
   362→      if (tok.type === TokenType.LBRACE && left.kind === "ident") {
   363→        // Lookahead: 다음 토큰이 ident이고, 그 다음이 :인지 확인
   364→        if (this.pos + 1 < this.tokens.length &&
   365→            this.tokens[this.pos + 1].type === TokenType.IDENT &&
   366→            this.pos + 2 < this.tokens.length &&
   367→            this.tokens[this.pos + 2].type === TokenType.COLON) {
   368→          this.advance(); // {
   369→          const fields: { name: string; value: Expr }[] = [];
   370→          if (!this.check(TokenType.RBRACE)) {
   371→            do {
   372→              const name = this.expectIdent("field name");
   373→              this.expect(TokenType.COLON, "expected ':' after field name");
   374→              const value = this.parseExpr(0);
   375→              fields.push({ name, value });
   376→            } while (this.match(TokenType.COMMA));
   377→          }
   378→          this.expect(TokenType.RBRACE, "expected '}'");
   379→          left = { kind: "struct_lit", structName: left.name, fields, line: left.line, col: left.col };
   380→          continue;
   381→        }
   382→      }
   383→
   384→      const bp = infixBP(tok.type);
   385→      if (bp <= minBP) break;
   386→
   387→      left = this.led(left, bp);
   388→    }
   389→
   390→    return left;
   391→  }
   392→
   393→  // nud — prefix 위치
   394→  private nud(): Expr {
   395→    const tok = this.peek();
   396→
   397→    // 정수 리터럴
   398→    if (tok.type === TokenType.INT_LIT) {
   399→      this.advance();
   400→      const raw = tok.lexeme.replace(/_/g, "");
   401→      return { kind: "int_lit", value: parseInt(raw, 10), line: tok.line, col: tok.col };
   402→    }
   403→
   404→    // 부동소수점 리터럴
   405→    if (tok.type === TokenType.FLOAT_LIT) {
   406→      this.advance();
   407→      const raw = tok.lexeme.replace(/_/g, "");
   408→      return { kind: "float_lit", value: parseFloat(raw), line: tok.line, col: tok.col };
   409→    }
   410→
   411→    // 문자열 리터럴
   412→    if (tok.type === TokenType.STRING_LIT) {
   413→      this.advance();
   414→      return { kind: "string_lit", value: tok.lexeme, line: tok.line, col: tok.col };
   415→    }
   416→
   417→    // 불리언 리터럴
   418→    if (tok.type === TokenType.TRUE) {
   419→      this.advance();
   420→      return { kind: "bool_lit", value: true, line: tok.line, col: tok.col };
   421→    }
   422→    if (tok.type === TokenType.FALSE) {
   423→      this.advance();
   424→      return { kind: "bool_lit", value: false, line: tok.line, col: tok.col };
   425→    }
   426→
   427→    // 식별자 (channel도 식 위치에서는 함수 이름으로 사용)
   428→    if (tok.type === TokenType.IDENT || tok.type === TokenType.TYPE_CHANNEL) {
   429→      this.advance();
   430→      return { kind: "ident", name: tok.lexeme, line: tok.line, col: tok.col };
   431→    }
   432→
   433→    // 단항 연산자: - !
   434→    if (tok.type === TokenType.MINUS || tok.type === TokenType.NOT) {
   435→      this.advance();
   436→      const operand = this.parseExpr(BP_UNARY);
   437→      return { kind: "unary", op: tok.lexeme, operand, line: tok.line, col: tok.col };
   438→    }
   439→
   440→    // 괄호 그룹: ( expr )
   441→    if (tok.type === TokenType.LPAREN) {
   442→      this.advance();
   443→      const expr = this.parseExpr(0);
   444→      this.expect(TokenType.RPAREN, "expected ')'");
   445→      return expr;
   446→    }
   447→
   448→    // 배열 리터럴: [ elem, ... ]
   449→    if (tok.type === TokenType.LBRACKET) {
   450→      return this.parseArrayLit();
   451→    }
   452→
   453→    // if 식 (식 위치)
   454→    if (tok.type === TokenType.IF) {
   455→      return this.parseIfExpr();
   456→    }
   457→
   458→    // match 식 (식 위치)
   459→    if (tok.type === TokenType.MATCH) {
   460→      return this.parseMatchExpr();
   461→    }
   462→
   463→    // 함수 리터럴 (람다): fn(x: i32) -> i32 { x + 1 }
   464→    if (tok.type === TokenType.FN) {
   465→      return this.parseFnLit();
   466→    }
   467→
   468→    this.error(`unexpected token: ${tok.lexeme}`, tok);
   469→    this.advance();
   470→    return { kind: "ident", name: "__error__", line: tok.line, col: tok.col };
   471→  }
   472→
   473→  // led — infix/postfix 위치
   474→  private led(left: Expr, bp: number): Expr {
   475→    const tok = this.peek();
   476→
   477→    // 이항 연산자
   478→    if (
   479→      tok.type === TokenType.PLUS || tok.type === TokenType.MINUS ||
   480→      tok.type === TokenType.STAR || tok.type === TokenType.SLASH ||
   481→      tok.type === TokenType.PERCENT ||
   482→      tok.type === TokenType.EQEQ || tok.type === TokenType.NEQ ||
   483→      tok.type === TokenType.LT || tok.type === TokenType.GT ||
   484→      tok.type === TokenType.LTEQ || tok.type === TokenType.GTEQ ||
   485→      tok.type === TokenType.AND || tok.type === TokenType.OR
   486→    ) {
   487→      this.advance();
   488→      const right = this.parseExpr(bp); // left-associative
   489→      return { kind: "binary", op: tok.lexeme, left, right, line: tok.line, col: tok.col };
   490→    }
   491→
   492→    // 함수 호출: expr(args)
   493→    if (tok.type === TokenType.LPAREN) {
   494→      this.advance();
   495→      const args: Expr[] = [];
   496→      if (!this.check(TokenType.RPAREN)) {
   497→        do {
   498→          args.push(this.parseExpr(0));
   499→        } while (this.match(TokenType.COMMA));
   500→      }
   501→      this.expect(TokenType.RPAREN, "expected ')' after arguments");
   502→      return { kind: "call", callee: left, args, line: tok.line, col: tok.col };
   503→    }
   504→
   505→    // 인덱스: expr[index]
   506→    if (tok.type === TokenType.LBRACKET) {
   507→      this.advance();
   508→      const index = this.parseExpr(0);
   509→      this.expect(TokenType.RBRACKET, "expected ']'");
   510→      return { kind: "index", object: left, index, line: tok.line, col: tok.col };
   511→    }
   512→
   513→    // 필드 접근: expr.field
   514→    if (tok.type === TokenType.DOT) {
   515→      this.advance();
   516→      const field = this.expectIdent("field name");
   517→      return { kind: "field_access", object: left, field, line: tok.line, col: tok.col };
   518→    }
   519→
   520→    // try 연산자: expr?
   521→    if (tok.type === TokenType.QUESTION) {
   522→      this.advance();
   523→      return { kind: "try", operand: left, line: tok.line, col: tok.col };
   524→    }
   525→
   526→    // 할당은 ExprStmt에서 처리하므로 여기선 패스
   527→    // EQ가 여기 오면 식 끝으로 처리
   528→    this.error(`unexpected operator: ${tok.lexeme}`, tok);
   529→    this.advance();
   530→    return left;
   531→  }
   532→
   533→  // ============================================================
   534→  // 복합 식 파싱
   535→  // ============================================================
   536→
   537→  // 배열 리터럴: [a, b, c]
   538→  private parseArrayLit(): Expr {
   539→    const tok = this.advance(); // [
   540→    const elements: Expr[] = [];
   541→    if (!this.check(TokenType.RBRACKET)) {
   542→      do {
   543→        elements.push(this.parseExpr(0));
   544→      } while (this.match(TokenType.COMMA));
   545→    }
   546→    this.expect(TokenType.RBRACKET, "expected ']'");
   547→    return { kind: "array_lit", elements, line: tok.line, col: tok.col };
   548→  }
   549→
   550→  // 구조체 리터럴: { name: expr, ... }
   551→  // if 식 (식 위치, else 필수 — SPEC_06)
   552→  private parseIfExpr(): Expr {
   553→    const tok = this.advance(); // if
   554→    const condition = this.parseExpr(0);
   555→    this.expect(TokenType.LBRACE, "expected '{' after if condition");
   556→    const then = this.parseBlockExprs();
   557→    this.expect(TokenType.ELSE, "if expression requires else branch");
   558→    this.expect(TokenType.LBRACE, "expected '{' after else");
   559→    const else_ = this.parseBlockExprs();
   560→    return { kind: "if_expr", condition, then, else_, line: tok.line, col: tok.col };
   561→  }
   562→
   563→  // match 식 (식 위치)
   564→  private parseMatchExpr(): Expr {
   565→    const tok = this.advance(); // match
   566→    const subject = this.parseExpr(0);
   567→    this.expect(TokenType.LBRACE, "expected '{' after match expression");
   568→    const arms = this.parseMatchArms();
   569→    this.expect(TokenType.RBRACE, "expected '}' to close match");
   570→    return { kind: "match_expr", subject, arms, line: tok.line, col: tok.col };
   571→  }
   572→
   573→  // 블록 내 식 목록 (if/match 식의 body) → } 소비
   574→  private parseBlockExprs(): Expr[] {
   575→    const exprs: Expr[] = [];
   576→    while (!this.check(TokenType.RBRACE) && !this.isAtEnd()) {
   577→      exprs.push(this.parseExpr(0));
   578→    }
   579→    this.expect(TokenType.RBRACE, "expected '}'");
   580→    return exprs;
   581→  }
   582→
   583→  // ============================================================
   584→  // match arms
   585→  // ============================================================
   586→
   587→  private parseMatchArms(): MatchArm[] {
   588→    const arms: MatchArm[] = [];
   589→    while (!this.check(TokenType.RBRACE) && !this.isAtEnd()) {
   590→      const pattern = this.parsePattern();
   591→      this.expect(TokenType.ARROW, "expected '=>' after pattern");
   592→
   593→      let body: Expr;
   594→      if (this.check(TokenType.LBRACE)) {
   595→        // 블록 body
   596→        const bTok = this.advance(); // {
   597→        const stmts: Stmt[] = [];
   598→        while (!this.check(TokenType.RBRACE) && !this.isAtEnd()) {
   599→          stmts.push(this.parseStmt());
   600→        }
   601→        this.expect(TokenType.RBRACE, "expected '}'");
   602→        // 블록의 마지막 문이 ExprStmt면 그 식이 반환값
   603→        const lastExpr = stmts.length > 0 && stmts[stmts.length - 1].kind === "expr_stmt"
   604→          ? (stmts[stmts.length - 1] as any).expr
   605→          : null;
   606→        body = { kind: "block_expr", stmts: stmts.slice(0, lastExpr ? -1 : stmts.length), expr: lastExpr, line: bTok.line, col: bTok.col };
   607→      } else {
   608→        body = this.parseExpr(0);
   609→      }
   610→
   611→      this.match(TokenType.COMMA); // trailing comma optional
   612→      arms.push({ pattern, body });
   613→    }
   614→    return arms;
   615→  }
   616→
   617→  // 함수 리터럴: fn(x: i32, y: i32) -> i32 { x + y }
   618→  private parseFnLit(): Expr {
   619→    const kw = this.advance(); // fn
   620→    this.expect(TokenType.LPAREN, "expected '(' after fn");
   621→
   622→    const params: FnParam[] = [];
   623→    if (!this.check(TokenType.RPAREN)) {
   624→      do {
   625→        const name = this.expectIdent("parameter name");
   626→        let type: TypeAnnotation | undefined = undefined;
   627→        if (this.match(TokenType.COLON)) {
   628→          type = this.parseType();
   629→        }
   630→        params.push({ name, type });
   631→      } while (this.match(TokenType.COMMA));
   632→    }
   633→    this.expect(TokenType.RPAREN, "expected ')' after parameters");
   634→
   635→    let returnType: TypeAnnotation | undefined = undefined;
   636→    if (this.match(TokenType.RARROW)) {
   637→      returnType = this.parseType();
   638→    }
   639→
   640→    // body
   641→    let body: Expr;
   642→    if (this.check(TokenType.LBRACE)) {
   643→      const bTok = this.advance(); // {
   644→      const stmts: Stmt[] = [];
   645→      while (!this.check(TokenType.RBRACE) && !this.isAtEnd()) {
   646→        stmts.push(this.parseStmt());
   647→      }
   648→      this.expect(TokenType.RBRACE, "expected '}'");
   649→      const lastExpr = stmts.length > 0 && stmts[stmts.length - 1].kind === "expr_stmt"
   650→        ? (stmts[stmts.length - 1] as any).expr
   651→        : null;
   652→      body = { kind: "block_expr", stmts: stmts.slice(0, lastExpr ? -1 : stmts.length), expr: lastExpr, line: bTok.line, col: bTok.col };
   653→    } else {
   654→      body = this.parseExpr(0);
   655→    }
   656→
   657→    return { kind: "fn_lit", params, returnType, body, line: kw.line, col: kw.col };
   658→  }
   659→
   660→  // ============================================================
   661→  // 패턴 파싱 (SPEC_05 Q8)
   662→  // ============================================================
   663→
   664→  private parsePattern(): Pattern {
   665→    const tok = this.peek();
   666→
   667→    // _ (wildcard)
   668→    if (tok.type === TokenType.IDENT && tok.lexeme === "_") {
   669→      this.advance();
   670→      return { kind: "wildcard" };
   671→    }
   672→
   673→    // Ok(p), Err(p), Some(p), None
   674→    if (tok.type === TokenType.IDENT) {
   675→      if (tok.lexeme === "Ok" || tok.lexeme === "Err" || tok.lexeme === "Some") {
   676→        this.advance();
   677→        this.expect(TokenType.LPAREN, `expected '(' after ${tok.lexeme}`);
   678→        const inner = this.parsePattern();
   679→        this.expect(TokenType.RPAREN, "expected ')'");
   680→        if (tok.lexeme === "Ok") return { kind: "ok", inner };
   681→        if (tok.lexeme === "Err") return { kind: "err", inner };
   682→        return { kind: "some", inner };
   683→      }
   684→      if (tok.lexeme === "None") {
   685→        this.advance();
   686→        return { kind: "none" };
   687→      }
   688→      // 일반 식별자 바인딩
   689→      this.advance();
   690→      return { kind: "ident", name: tok.lexeme };
   691→    }
   692→
   693→    // 리터럴 패턴
   694→    if (tok.type === TokenType.INT_LIT || tok.type === TokenType.FLOAT_LIT ||
   695→        tok.type === TokenType.STRING_LIT || tok.type === TokenType.TRUE ||
   696→        tok.type === TokenType.FALSE) {
   697→      const expr = this.nud();
   698→      return { kind: "literal", value: expr };
   699→    }
   700→
   701→    // 단항 마이너스 (음수 리터럴 패턴)
   702→    if (tok.type === TokenType.MINUS) {
   703→      const expr = this.nud(); // unary minus
   704→      return { kind: "literal", value: expr };
   705→    }
   706→
   707→    this.error("expected pattern", tok);
   708→    this.advance();
   709→    return { kind: "wildcard" };
   710→  }
   711→
   712→  // ============================================================
   713→  // 타입 파싱
   714→  // ============================================================
   715→
   716→  private parseType(): TypeAnnotation {
   717→    const tok = this.peek();
   718→
   719→    // fn(T1, T2) -> R 함수 타입
   720→    if (tok.type === TokenType.FN) {
   721→      this.advance(); // fn
   722→      this.expect(TokenType.LPAREN, "expected '(' after fn");
   723→
   724→      const params: TypeAnnotation[] = [];
   725→      if (!this.check(TokenType.RPAREN)) {
   726→        do {
   727→          params.push(this.parseType());
   728→        } while (this.match(TokenType.COMMA));
   729→      }
   730→
   731→      this.expect(TokenType.RPAREN, "expected ')' after fn params");
   732→      this.expect(TokenType.RARROW, "expected '->' in fn type");
   733→      const returnType = this.parseType();
   734→
   735→      return { kind: "fn", params, returnType };
   736→    }
   737→
   738→    switch (tok.type) {
   739→      case TokenType.TYPE_I32: this.advance(); return { kind: "i32" };
   740→      case TokenType.TYPE_I64: this.advance(); return { kind: "i64" };
   741→      case TokenType.TYPE_F64: this.advance(); return { kind: "f64" };
   742→      case TokenType.TYPE_BOOL: this.advance(); return { kind: "bool" };
   743→      case TokenType.TYPE_STRING: this.advance(); return { kind: "string" };
   744→      case TokenType.TYPE_VOID: this.advance(); return { kind: "void" };
   745→      default:
   746→        break;
   747→    }
   748→
   749→    // [T] → 배열
   750→    if (tok.type === TokenType.LBRACKET) {
   751→      this.advance();
   752→      const element = this.parseType();
   753→      this.expect(TokenType.RBRACKET, "expected ']' for array type");
   754→      return { kind: "array", element };
   755→    }
   756→
   757→    // channel<T>
   758→    if (tok.type === TokenType.TYPE_CHANNEL) {
   759→      this.advance();
   760→      this.expect(TokenType.LT, "expected '<' after channel");
   761→      const element = this.parseType();
   762→      this.expect(TokenType.GT, "expected '>' for channel type");
   763→      return { kind: "channel", element };
   764→    }
   765→
   766→    // IDENT: 타입 파라미터(T, K, V) 또는 Generic/Struct 타입 [STEP B-3]
   767→    if (tok.type === TokenType.IDENT) {
   768→      const name = tok.lexeme;
   769→      this.advance();
   770→
   771→      // 단일 대문자 → type_param (T, K, V)
   772→      if (name.length === 1 && name >= 'A' && name <= 'Z') {
   773→        return { kind: "type_param", name };
   774→      }
   775→
   776→      // Option<T>, Result<T,E>, Generic 타입, 커스텀 struct
   777→      if (this.check(TokenType.LT)) {
   778→        this.advance(); // LT 소비
   779→        const typeArgs: TypeAnnotation[] = [];
   780→        do {
   781→          typeArgs.push(this.parseType());
   782→        } while (this.match(TokenType.COMMA));
   783→        this.expect(TokenType.GT, "expected '>' after type arguments");
   784→
   785→        // 내장 제네릭 타입 매핑
   786→        if (name === "Option") return { kind: "option", element: typeArgs[0] };
   787→        if (name === "Result") return { kind: "result", ok: typeArgs[0], err: typeArgs[1] };
   788→        return { kind: "generic_ref", name, typeArgs };
   789→      }
   790→
   791→      return { kind: "struct_ref", name };
   792→    }
   793→
   794→    this.error(`expected type, got ${tok.lexeme}`, tok);
   795→    this.advance();
   796→    return { kind: "i32" }; // fallback
   797→  }
   798→
   799→  // ============================================================
   800→  // 유틸리티
   801→  // ============================================================
   802→
   803→  private peek(): Token {
   804→    return this.tokens[this.pos];
   805→  }
   806→
   807→  private advance(): Token {
   808→    const tok = this.tokens[this.pos];
   809→    if (!this.isAtEnd()) this.pos++;
   810→    return tok;
   811→  }
   812→
   813→  private check(type: TokenType): boolean {
   814→    return this.peek().type === type;
   815→  }
   816→
   817→  private match(type: TokenType): boolean {
   818→    if (this.check(type)) {
   819→      this.advance();
   820→      return true;
   821→    }
   822→    return false;
   823→  }
   824→
   825→  private expect(type: TokenType, message: string): Token {
   826→    if (this.check(type)) {
   827→      return this.advance();
   828→    }
   829→    const tok = this.peek();
   830→    this.error(`${message} (got ${tok.type}: "${tok.lexeme}")`, tok);
   831→    throw new Error(message);
   832→  }
   833→
   834→  private expectIdent(context: string): string {
   835→    const tok = this.peek();
   836→    if (tok.type === TokenType.IDENT) {
   837→      this.advance();
   838→      return tok.lexeme;
   839→    }
   840→    this.error(`expected ${context} (got ${tok.type}: "${tok.lexeme}")`, tok);
   841→    throw new Error(`expected ${context}`);
   842→  }
   843→
   844→  private isAtEnd(): boolean {
   845→    return this.peek().type === TokenType.EOF;
   846→  }
   847→
   848→  private isStmtStart(): boolean {
   849→    const t = this.peek().type;
   850→    return t === TokenType.VAR || t === TokenType.LET || t === TokenType.CONST ||
   851→           t === TokenType.FN || t === TokenType.STRUCT || t === TokenType.IF || t === TokenType.MATCH ||
   852→           t === TokenType.FOR || t === TokenType.WHILE || t === TokenType.BREAK || t === TokenType.CONTINUE ||
   853→           t === TokenType.SPAWN || t === TokenType.RETURN;
   854→  }
   855→
   856→  private error(message: string, tok: Token): void {
   857→    this.errors.push({ message, line: tok.line, col: tok.col });
   858→  }
   859→
   860→  private synchronize(): void {
   861→    while (!this.isAtEnd()) {
   862→      if (this.isStmtStart()) return;
   863→      if (this.check(TokenType.RBRACE)) {
   864→        this.advance();
   865→        return;
   866→      }
   867→      this.advance();
   868→    }
   869→  }
   870→}
   871→

