// FreeLang v8 ML - 손실 함수 (Phase 4 확장)
import { Value } from './autodiff';

// ============================================================
// MSE Loss (Mean Squared Error)
// ============================================================

export function mse(pred: Value[], target: number[]): Value {
  if (pred.length !== target.length) throw new Error('mse: length 불일치');
  let loss = Value.from(0);
  for (let i = 0; i < pred.length; i++) {
    const diff = pred[i].add(Value.from(-target[i]));
    loss = loss.add(diff.pow(2));
  }
  return loss.mul(Value.from(1 / pred.length));
}

// ============================================================
// MAE Loss (Mean Absolute Error)
// ============================================================

export function mae(pred: Value[], target: number[]): Value {
  if (pred.length !== target.length) throw new Error('mae: length 불일치');
  let loss = Value.from(0);
  for (let i = 0; i < pred.length; i++) {
    const diff = pred[i].data - target[i];
    loss = loss.add(Value.from(Math.abs(diff)));
  }
  return loss.mul(Value.from(1 / pred.length));
}

// ============================================================
// Huber Loss (MSE + MAE 결합, 이상치 강건)
// ============================================================

export function huber(pred: Value[], target: number[], delta = 1.0): Value {
  if (pred.length !== target.length) throw new Error('huber: length 불일치');
  let loss = Value.from(0);
  for (let i = 0; i < pred.length; i++) {
    const diff = Math.abs(pred[i].data - target[i]);
    if (diff <= delta) {
      const v = pred[i].add(Value.from(-target[i]));
      loss = loss.add(v.pow(2).mul(Value.from(0.5)));
    } else {
      loss = loss.add(Value.from(delta * (diff - 0.5 * delta)));
    }
  }
  return loss.mul(Value.from(1 / pred.length));
}

// ============================================================
// Binary Cross-Entropy Loss
// ============================================================

export function binaryCrossEntropy(pred: Value[], target: number[]): Value {
  let loss = Value.from(0);
  for (let i = 0; i < pred.length; i++) {
    const p = Math.max(Math.min(pred[i].data, 1 - 1e-7), 1e-7); // clip
    const y = target[i];
    loss = loss.add(Value.from(-(y * Math.log(p) + (1 - y) * Math.log(1 - p))));
  }
  return loss.mul(Value.from(1 / pred.length));
}

// ============================================================
// Softmax Cross-Entropy (다중 분류)
// ============================================================

export function softmaxCrossEntropy(logits: Value[], targetClass: number): Value {
  // softmax
  const maxVal = Math.max(...logits.map(v => v.data));
  const exps = logits.map(v => Math.exp(v.data - maxVal));
  const sumExp = exps.reduce((a, b) => a + b, 0);
  const probs = exps.map(e => e / sumExp);

  // cross-entropy: -log(p[targetClass])
  const loss = -Math.log(Math.max(probs[targetClass], 1e-7));
  const out = Value.from(loss);

  // 역전파: dL/dlogit_i = p_i - 1(i==target)
  (out as any)._backward = () => {
    for (let i = 0; i < logits.length; i++) {
      const grad = (probs[i] - (i === targetClass ? 1 : 0)) * out.grad;
      (logits[i] as any).grad += grad;
    }
  };
  // prev 연결
  (out as any)._prev = new Set(logits);

  return out;
}

// ============================================================
// Hinge Loss (SVM)
// ============================================================

export function hingeLoss(pred: Value[], target: number[]): Value {
  if (pred.length !== target.length) throw new Error('hinge: length 불일치');
  let loss = Value.from(0);
  for (let i = 0; i < pred.length; i++) {
    const margin = 1 - target[i] * pred[i].data;
    if (margin > 0) loss = loss.add(Value.from(margin));
  }
  return loss.mul(Value.from(1 / pred.length));
}

