// FreeLang v8 ML - Trainer (학습 루프 자동화)

import { Value } from './autodiff';
import { Module } from './nn';
import { Adam } from './optimizer';
import { DataLoader, Dataset, Batch } from './dataloader';
import { mse, softmaxCrossEntropy } from './loss';

export type LossType = "mse" | "cross_entropy";

export type TrainConfig = {
  epochs: number;
  lr?: number;
  batchSize?: number;
  shuffle?: boolean;
  verbose?: boolean;
  logEvery?: number;
  lossType?: LossType;
};

export type TrainHistory = {
  trainLoss: number[];
  valLoss: number[];
  epochs: number;
};

// ============================================================
// Trainer
// ============================================================

export class Trainer {
  private optim: Adam;
  private history: TrainHistory = { trainLoss: [], valLoss: [], epochs: 0 };

  constructor(
    public model: Module,
    public config: TrainConfig
  ) {
    this.optim = new Adam(config.lr ?? 0.001);
  }

  // ============================================================
  // 단일 배치 학습 스텝
  // ============================================================

  private step(X: number[][], y: number[][]): number {
    let totalLoss = Value.from(0);
    const lossType = this.config.lossType ?? "mse";

    for (let i = 0; i < X.length; i++) {
      const input = X[i].map(v => Value.from(v));
      const output = this.model.forward(input);

      let loss: Value;
      if (lossType === "cross_entropy") {
        const targetClass = y[i].indexOf(Math.max(...y[i]));
        loss = softmaxCrossEntropy(output, targetClass);
      } else {
        loss = mse(output, y[i]);
      }
      totalLoss = totalLoss.add(loss);
    }

    const avgLoss = totalLoss.mul(Value.from(1 / X.length));

    this.optim.zeroGrad(this.model.params());
    avgLoss.backward();
    this.optim.step(this.model.params());

    return avgLoss.data;
  }

  // ============================================================
  // 전체 학습
  // ============================================================

  fit(
    trainData: Dataset,
    valData?: Dataset
  ): TrainHistory {
    const loader = new DataLoader(trainData, this.config.batchSize ?? 32, this.config.shuffle ?? true);
    const verbose = this.config.verbose ?? true;
    const logEvery = this.config.logEvery ?? Math.max(1, Math.floor(this.config.epochs / 10));

    for (let epoch = 0; epoch < this.config.epochs; epoch++) {
      let epochLoss = 0;
      let batchCount = 0;

      for (const batch of loader.batches()) {
        epochLoss += this.step(batch.X, batch.y);
        batchCount++;
      }

      const avgLoss = epochLoss / batchCount;
      this.history.trainLoss.push(avgLoss);

      // 검증
      let valLoss = 0;
      if (valData) {
        valLoss = this.evaluate(valData);
        this.history.valLoss.push(valLoss);
      }

      if (verbose && (epoch + 1) % logEvery === 0) {
        const msg = valData
          ? `Epoch ${epoch + 1}/${this.config.epochs} — loss: ${avgLoss.toFixed(6)}, val_loss: ${valLoss.toFixed(6)}`
          : `Epoch ${epoch + 1}/${this.config.epochs} — loss: ${avgLoss.toFixed(6)}`;
        console.log(msg);
      }
    }

    this.history.epochs = this.config.epochs;
    return this.history;
  }

  // ============================================================
  // 평가 (손실만)
  // ============================================================

  evaluate(data: Dataset): number {
    let totalLoss = 0;
    const lossType = this.config.lossType ?? "mse";

    for (let i = 0; i < data.X.length; i++) {
      const input = data.X[i].map(v => Value.from(v));
      const output = this.model.forward(input);
      let loss: Value;
      if (lossType === "cross_entropy") {
        const targetClass = data.y[i].indexOf(Math.max(...data.y[i]));
        loss = softmaxCrossEntropy(output, targetClass);
      } else {
        loss = mse(output, data.y[i]);
      }
      totalLoss += loss.data;
    }

    return totalLoss / data.X.length;
  }

  // ============================================================
  // 예측
  // ============================================================

  predict(X: number[][]): number[][] {
    return X.map(x => {
      const input = x.map(v => Value.from(v));
      return this.model.forward(input).map(v => v.data);
    });
  }

  // 분류 정확도
  accuracy(X: number[][], yTrue: number[][]): number {
    let correct = 0;
    for (let i = 0; i < X.length; i++) {
      const input = X[i].map(v => Value.from(v));
      const output = this.model.forward(input).map(v => v.data);
      const pred = output.indexOf(Math.max(...output));
      const truth = yTrue[i].indexOf(Math.max(...yTrue[i]));
      if (pred === truth) correct++;
    }
    return correct / X.length;
  }

  getHistory(): TrainHistory { return this.history; }
}

