// FreeLang v8 ML - Neural Network 레이어 (Phase 4 확장)
import { Value } from './autodiff';

// ============================================================
// 기본 인터페이스
// ============================================================

export interface Module {
  forward(x: Value[]): Value[];
  params(): Value[];
  name: string;
}

// ============================================================
// Neuron (단일 뉴런 — tanh 활성화)
// ============================================================

export class Neuron implements Module {
  name = "Neuron";
  w: Value[];
  b: Value;

  constructor(nin: number, private nonlin: boolean = true) {
    const scale = Math.sqrt(2 / nin); // He 초기화
    this.w = Array.from({ length: nin }, () => Value.from((Math.random() * 2 - 1) * scale));
    this.b = Value.from(0);
  }

  forward(x: Value[]): Value[] {
    let act = this.b;
    for (let i = 0; i < this.w.length; i++)
      act = act.add(this.w[i].mul(x[i]));
    return [this.nonlin ? act.tanh() : act];
  }

  params(): Value[] { return [...this.w, this.b]; }
}

// ============================================================
// Linear (완전연결 레이어)
// ============================================================

export class Linear implements Module {
  name = "Linear";
  w: Value[][];  // [out, in]
  b: Value[];    // [out]

  constructor(public nin: number, public nout: number) {
    const scale = Math.sqrt(2 / nin);
    this.w = Array.from({ length: nout }, () =>
      Array.from({ length: nin }, () => Value.from((Math.random() * 2 - 1) * scale))
    );
    this.b = Array.from({ length: nout }, () => Value.from(0));
  }

  forward(x: Value[]): Value[] {
    return Array.from({ length: this.nout }, (_, i) => {
      let sum = this.b[i];
      for (let j = 0; j < this.nin; j++) sum = sum.add(this.w[i][j].mul(x[j]));
      return sum;
    });
  }

  params(): Value[] {
    return [...this.w.flat(), ...this.b];
  }
}

// ============================================================
// ReLU 활성화
// ============================================================

export class ReLU implements Module {
  name = "ReLU";
  forward(x: Value[]): Value[] { return x.map(v => v.relu()); }
  params(): Value[] { return []; }
}

// ============================================================
// Sigmoid 활성화
// ============================================================

export class Sigmoid implements Module {
  name = "Sigmoid";
  forward(x: Value[]): Value[] {
    return x.map(v => {
      const out = new Value(1 / (1 + Math.exp(-v.data)), [v]);
      const s = out.data;
      (out as any)._backward = () => { (v as any).grad += s * (1 - s) * out.grad; };
      return out;
    });
  }
  params(): Value[] { return []; }
}

// ============================================================
// Tanh 활성화
// ============================================================

export class Tanh implements Module {
  name = "Tanh";
  forward(x: Value[]): Value[] { return x.map(v => v.tanh()); }
  params(): Value[] { return []; }
}

// ============================================================
// Softmax (추론 전용 — 그래디언트 없음)
// ============================================================

export class Softmax implements Module {
  name = "Softmax";
  forward(x: Value[]): Value[] {
    const maxVal = Math.max(...x.map(v => v.data));
    const exps = x.map(v => Math.exp(v.data - maxVal));
    const sum = exps.reduce((a, b) => a + b, 0);
    return exps.map(e => Value.from(e / sum));
  }
  params(): Value[] { return []; }
}

// ============================================================
// Dropout (학습 시만 적용)
// ============================================================

export class Dropout implements Module {
  name = "Dropout";
  private training = true;

  constructor(public rate: number = 0.5) {}

  train() { this.training = true; }
  eval()  { this.training = false; }

  forward(x: Value[]): Value[] {
    if (!this.training) return x;
    return x.map(v => {
      if (Math.random() < this.rate) return Value.from(0);
      const scale = 1 / (1 - this.rate);
      return v.mul(Value.from(scale));
    });
  }
  params(): Value[] { return []; }
}

// ============================================================
// BatchNorm1d (간소화 — 추론시 running stats 사용)
// ============================================================

export class BatchNorm1d implements Module {
  name = "BatchNorm1d";
  gamma: Value[];
  beta: Value[];
  runningMean: number[];
  runningVar: number[];
  private training = true;

  constructor(public features: number, public eps = 1e-5, public momentum = 0.1) {
    this.gamma = Array.from({ length: features }, () => Value.from(1));
    this.beta  = Array.from({ length: features }, () => Value.from(0));
    this.runningMean = Array(features).fill(0);
    this.runningVar  = Array(features).fill(1);
  }

  train() { this.training = true; }
  eval()  { this.training = false; }

  forward(x: Value[]): Value[] {
    if (this.training) {
      const mean = x.reduce((s, v) => s + v.data, 0) / x.length;
      const variance = x.reduce((s, v) => s + (v.data - mean) ** 2, 0) / x.length;
      // running stats 업데이트
      for (let i = 0; i < this.features; i++) {
        this.runningMean[i] = (1 - this.momentum) * this.runningMean[i] + this.momentum * mean;
        this.runningVar[i]  = (1 - this.momentum) * this.runningVar[i]  + this.momentum * variance;
      }
      return x.map((v, i) => {
        const norm = Value.from((v.data - mean) / Math.sqrt(variance + this.eps));
        return this.gamma[i].mul(norm).add(this.beta[i]);
      });
    } else {
      return x.map((v, i) => {
        const norm = Value.from((v.data - this.runningMean[i]) / Math.sqrt(this.runningVar[i] + this.eps));
        return this.gamma[i].mul(norm).add(this.beta[i]);
      });
    }
  }

  params(): Value[] { return [...this.gamma, ...this.beta]; }
}

// ============================================================
// Sequential (레이어 체인)
// ============================================================

export class Sequential implements Module {
  name = "Sequential";

  constructor(public layers: Module[]) {}

  forward(x: Value[]): Value[] {
    let out = x;
    for (const layer of this.layers) out = layer.forward(out);
    return out;
  }

  params(): Value[] { return this.layers.flatMap(l => l.params()); }

  add(layer: Module): Sequential {
    this.layers.push(layer);
    return this;
  }

  toString(): string {
    return `Sequential(\n${this.layers.map((l, i) => `  (${i}): ${l.name}`).join('\n')}\n)`;
  }
}

// ============================================================
// Layer (하위 호환용 — Neuron 배열)
// ============================================================

export class Layer implements Module {
  name = "Layer";
  neurons: Neuron[];

  constructor(nin: number, nout: number) {
    this.neurons = Array.from({ length: nout }, () => new Neuron(nin));
  }

  forward(x: Value[]): Value[] {
    return this.neurons.map(n => n.forward(x)[0]);
  }

  params(): Value[] { return this.neurons.flatMap(n => n.params()); }
}

// ============================================================
// MLP (하위 호환용 — Layer 배열)
// ============================================================

export class MLP implements Module {
  name = "MLP";
  layers: Layer[];

  constructor(nin: number, nouts: number[]) {
    const sizes = [nin, ...nouts];
    this.layers = [];
    for (let i = 0; i < nouts.length; i++)
      this.layers.push(new Layer(sizes[i], sizes[i + 1]));
  }

  forward(x: number[]): Value[] {
    let out: Value[] = x.map(v => Value.from(v));
    for (const layer of this.layers) out = layer.forward(out);
    return out;
  }

  params(): Value[] { return this.layers.flatMap(l => l.params()); }

  zeroGrad(): void {
    for (const p of this.params()) p.grad = 0;
  }
}

// ============================================================
// SGD (하위 호환용)
// ============================================================

export class SGD {
  constructor(public lr = 0.01) {}

  step(params: Value[]): void {
    for (const p of params) p.data -= this.lr * p.grad;
  }

  zeroGrad(params: Value[]): void {
    for (const p of params) p.grad = 0;
  }
}

