package main

import (
	"encoding/binary"
	"fmt"
	"math"
	"math/rand"
	"os"
)

// ==================================================
// Phase 8: N-Layer Transformer — End-to-End Backprop
//
// 구조:
//   Embedding [vocab, d]
//   N × TransformerBlock (각 레이어 독립 가중치)
//   Final LN + Proj [d, vocab]
//
// 핵심: Forward 시 레이어 간 activation 연결,
//       Backward 시 dX를 레이어 역순으로 전파
// ==================================================

// ─────────────────────────────────────────────────
// 단일 레이어 가중치
// ─────────────────────────────────────────────────

type NLayerBlock struct {
	Wq, Wk, Wv, Wo    [][]float64
	ln1Scale, ln1Bias  []float64
	W1, W2             [][]float64
	b1, b2             []float64
	ln2Scale, ln2Bias  []float64
}

func newNLayerBlock(d, ffn int) *NLayerBlock {
	scale  := math.Sqrt(2.0 / float64(d+d))
	fScale := math.Sqrt(2.0 / float64(d+ffn))
	return &NLayerBlock{
		Wq: make2DRand(d, d, scale),
		Wk: make2DRand(d, d, scale),
		Wv: make2DRand(d, d, scale),
		Wo: make2DRand(d, d, scale),
		ln1Scale: onesVec(d),
		ln1Bias:  zerosVec(d),
		W1: make2DRand(d, ffn, fScale),
		b1: zerosVec(ffn),
		W2: make2DRand(ffn, d, fScale),
		b2: zerosVec(d),
		ln2Scale: onesVec(d),
		ln2Bias:  zerosVec(d),
	}
}

// ─────────────────────────────────────────────────
// N-Layer 모델
// ─────────────────────────────────────────────────

type NLayerModel struct {
	vocabSize int
	dModel    int

// FreeLang GPT: Phase 5 - Transformer Blocks
// ==================================================
// Core transformer architecture components
// Status: 🟢 Implementation (Phase 5 Pilot)

module transformer

import tensor
import nn
import attention
import math
import arrays

// ==================================================
// 1. TRANSFORMER BLOCK RECORD
// ==================================================

record FFN {
  fc1: Linear,              // d_model -> 4*d_model
  fc2: Linear               // 4*d_model -> d_model
}

record TransformerBlock {
  mha: MultiHeadAttention,
  ln1: LayerNorm,
  ffn: FFN,
  ln2: LayerNorm
}

record GPTConfig {
  vocab_size: Int,
  d_model: Int,
  num_heads: Int,
  num_layers: Int,
  max_seq_len: Int
}

record GPTModel {
  token_embed: Variable,    // [vocab_size, d_model]
  pos_embed: Variable,      // [max_seq_len, d_model]
  blocks: Array[TransformerBlock],
  ln_final: LayerNorm,
  lm_head: Linear           // d_model -> vocab_size
}

// ==================================================
// 2. TRANSFORMER BLOCK INITIALIZATION
// ==================================================

// Initialize FFN layer
function ffn_init(d_model: Int, seed: Int) -> FFN = {
  let fc1 = linear_init(d_model, 4 * d_model, seed)
  let fc2 = linear_init(4 * d_model, d_model, seed + 1)

  FFN {
    fc1: fc1,
    fc2: fc2
  }
}

