// FreeLang v8 ML — BPE 토크나이저 (Phase 5)

// ============================================================
// 캐릭터 수준 토크나이저 (기본)
// ============================================================

export class CharTokenizer {
  private charToId: Map<string, number> = new Map();
  private idToChar: Map<number, string> = new Map();
  private _vocabSize: number = 0;

  // 특수 토큰
  static readonly PAD = 0;
  static readonly UNK = 1;
  static readonly BOS = 2;
  static readonly EOS = 3;

  constructor() {
    this.addToken("<PAD>");  // 0
    this.addToken("<UNK>");  // 1
    this.addToken("<BOS>");  // 2
    this.addToken("<EOS>");  // 3
  }

  private addToken(tok: string): number {
    if (this.charToId.has(tok)) return this.charToId.get(tok)!;
    const id = this._vocabSize++;
    this.charToId.set(tok, id);
    this.idToChar.set(id, tok);
    return id;
  }

  // 텍스트로부터 vocab 구축
  fit(text: string): void {
    const chars = Array.from(new Set(text.split(""))).sort();
    for (const ch of chars) this.addToken(ch);
  }

  // 텍스트 → 토큰 ID 배열
  encode(text: string, addBos = false, addEos = false): number[] {
    const ids: number[] = [];
    if (addBos) ids.push(CharTokenizer.BOS);
    for (const ch of text) {
      ids.push(this.charToId.get(ch) ?? CharTokenizer.UNK);
    }
    if (addEos) ids.push(CharTokenizer.EOS);
    return ids;
  }

  // 토큰 ID 배열 → 텍스트
  decode(ids: number[], skipSpecial = true): string {
    return ids
      .filter(id => !skipSpecial || id >= 4)
      .map(id => this.idToChar.get(id) ?? "?")
      .join("");
  }

  get vocabSize(): number { return this._vocabSize; }

  getVocab(): Map<string, number> { return new Map(this.charToId); }
}

// ============================================================
// BPE 토크나이저 (간소화 버전)
// ============================================================

type BpePair = [string, string];

export class BPETokenizer {
  private vocab: Map<string, number> = new Map();
  private merges: BpePair[] = [];
  private _vocabSize: number = 0;

  // 특수 토큰
  static readonly PAD_TOKEN = "<PAD>";
  static readonly UNK_TOKEN = "<UNK>";
  static readonly BOS_TOKEN = "<BOS>";
  static readonly EOS_TOKEN = "<EOS>";

  constructor() {
    this.addToken(BPETokenizer.PAD_TOKEN);
    this.addToken(BPETokenizer.UNK_TOKEN);
    this.addToken(BPETokenizer.BOS_TOKEN);
    this.addToken(BPETokenizer.EOS_TOKEN);
  }

  private addToken(tok: string): number {
    if (this.vocab.has(tok)) return this.vocab.get(tok)!;
    const id = this._vocabSize++;
    this.vocab.set(tok, id);
    return id;
  }

  // BPE 학습
  fit(text: string, targetVocabSize: number = 256): void {
    // 초기 캐릭터 vocab
    const chars = Array.from(new Set(text.split(""))).sort();
    for (const ch of chars) this.addToken(ch);

    // 단어를 캐릭터 시퀀스로 분해 (공백으로 단어 분리)
    const words = text.split(/\s+/).filter(w => w.length > 0);
    let corpus: string[][] = words.map(w => (w + " ").split(""));

    const maxMerges = targetVocabSize - this._vocabSize;
    for (let i = 0; i < maxMerges; i++) {
      const pairFreqs = this.getPairFreqs(corpus);
      if (pairFreqs.size === 0) break;

      // 가장 빈번한 쌍 선택
      let bestPair: BpePair | null = null;
      let bestFreq = 0;
      for (const [pair, freq] of pairFreqs) {
        if (freq > bestFreq) {
          bestFreq = freq;
          bestPair = pair.split("|") as BpePair;
        }
      }
      if (!bestPair || bestFreq < 2) break;

      // 병합
      this.merges.push(bestPair);
      const merged = bestPair[0] + bestPair[1];
      this.addToken(merged);
      corpus = this.applyMerge(corpus, bestPair, merged);
    }
  }

  private getPairFreqs(corpus: string[][]): Map<string, number> {
    const freqs = new Map<string, number>();
    for (const word of corpus) {
      for (let i = 0; i < word.length - 1; i++) {
        const key = `${word[i]}|${word[i + 1]}`;
        freqs.set(key, (freqs.get(key) ?? 0) + 1);
      }
    }
    return freqs;
  }

  private applyMerge(corpus: string[][], pair: BpePair, merged: string): string[][] {
    return corpus.map(word => {
      const result: string[] = [];
      let i = 0;
      while (i < word.length) {
        if (i < word.length - 1 && word[i] === pair[0] && word[i + 1] === pair[1]) {
          result.push(merged);
          i += 2;
        } else {
          result.push(word[i]);
          i++;
        }
      }
      return result;
    });
  }

  // 텍스트 → 토큰 ID
  encode(text: string, addBos = false, addEos = false): number[] {
    const tokens = this.tokenize(text);
    const ids: number[] = [];
    if (addBos) ids.push(0); // BOS=0 (내부 ID 방식 단순화)
    for (const tok of tokens) {
      ids.push(this.vocab.get(tok) ?? 1); // UNK=1
    }
    if (addEos) ids.push(1);
    return ids;
  }

  private tokenize(text: string): string[] {
    // 단순화: 캐릭터 단위 + 병합 적용
    let tokens = text.split("");
    for (const [a, b] of this.merges) {
      const merged = a + b;
      const result: string[] = [];
      let i = 0;
      while (i < tokens.length) {
        if (i < tokens.length - 1 && tokens[i] === a && tokens[i + 1] === b) {
          result.push(merged);
          i += 2;
        } else {
          result.push(tokens[i]);
          i++;
        }
      }
      tokens = result;
    }
    return tokens;
  }

  decode(ids: number[]): string {
    const reverseVocab = new Map<number, string>();
    for (const [tok, id] of this.vocab) reverseVocab.set(id, tok);
    return ids.map(id => reverseVocab.get(id) ?? "?").join("").replace(/ /g, " ");
  }

  get vocabSize(): number { return this._vocabSize; }
  getMerges(): BpePair[] { return [...this.merges]; }
}

// ============================================================
// 배치 패딩 유틸리티
// ============================================================

export function padSequences(seqs: number[][], padId = 0, maxLen?: number): number[][] {
  const length = maxLen ?? Math.max(...seqs.map(s => s.length));
  return seqs.map(s => {
    const padded = [...s];
    while (padded.length < length) padded.push(padId);
    return padded.slice(0, length);
  });
}

// 슬라이딩 윈도우로 학습 데이터 생성
export function makeNgramData(
  ids: number[],
  seqLen: number
): { inputs: number[][]; targets: number[][] } {
  const inputs: number[][] = [];
  const targets: number[][] = [];
  for (let i = 0; i + seqLen < ids.length; i++) {
    inputs.push(ids.slice(i, i + seqLen));
    targets.push(ids.slice(i + 1, i + seqLen + 1));
  }
  return { inputs, targets };
}

