// FreeLang v8 ML — Attention 메커니즘 (Phase 5)
import { Value } from './autodiff';

// ============================================================
// Scaled Dot-Product Attention
// score = softmax(QK^T / sqrt(d_k)) V
// ============================================================

export function scaledDotProductAttention(
  Q: Value[][],  // [seq, d_k]
  K: Value[][],  // [seq, d_k]
  V: Value[][],  // [seq, d_v]
  mask?: boolean[][]  // causal mask
): Value[][] {
  const seqLen = Q.length;
  const dk = Q[0].length;
  const scale = 1 / Math.sqrt(dk);

  // scores = Q @ K^T * scale: [seq, seq]
  const scores: Value[][] = Array.from({ length: seqLen }, () =>
    Array(seqLen).fill(null)
  );

  for (let i = 0; i < seqLen; i++) {
    for (let j = 0; j < seqLen; j++) {
      // causal mask: 미래 위치 마스킹
      if (mask && mask[i][j]) {
        scores[i][j] = Value.from(-1e9);
        continue;
      }
      let s = Value.from(0);
      for (let k = 0; k < dk; k++) {
        s = s.add(Q[i][k].mul(K[j][k]));
      }
      scores[i][j] = s.mul(Value.from(scale));
    }
  }

  // softmax over each row
  const attnWeights: Value[][] = scores.map(row => softmaxValues(row));

  // output = attnWeights @ V: [seq, d_v]
  const dv = V[0].length;
  const output: Value[][] = Array.from({ length: seqLen }, () =>
    Array(dv).fill(Value.from(0))
  );

  for (let i = 0; i < seqLen; i++) {
    for (let v = 0; v < dv; v++) {
      let sum = Value.from(0);
      for (let j = 0; j < seqLen; j++) {
        sum = sum.add(attnWeights[i][j].mul(V[j][v]));
      }
      output[i][v] = sum;
    }
  }

  return output;
}

// ============================================================
// Causal mask (하삼각 행렬 — 현재 위치 이후 마스킹)
// ============================================================

export function makeCausalMask(seqLen: number): boolean[][] {
  return Array.from({ length: seqLen }, (_, i) =>
    Array.from({ length: seqLen }, (_, j) => j > i)
  );
}

// ============================================================
// MultiHead Attention
// ============================================================

export class MultiHeadAttention {
  private Wq: Value[][];  // [d_model, d_model]
  private Wk: Value[][];
  private Wv: Value[][];
  private Wo: Value[][];  // output projection

  constructor(public dModel: number, public numHeads: number) {
    if (dModel % numHeads !== 0) {
      throw new Error(`d_model(${dModel})은 numHeads(${numHeads})의 배수여야 합니다`);
    }
    const scale = Math.sqrt(2 / dModel);
    this.Wq = makeWeight(dModel, dModel, scale);
    this.Wk = makeWeight(dModel, dModel, scale);
    this.Wv = makeWeight(dModel, dModel, scale);
    this.Wo = makeWeight(dModel, dModel, scale);
  }

  // x: [seq, d_model] → out: [seq, d_model]
  forward(x: Value[][], causal = true): Value[][] {
    const seqLen = x.length;
    const dk = Math.floor(this.dModel / this.numHeads);

    // Linear projections: Q,K,V
    const Q = matmul2D(x, this.Wq);  // [seq, d_model]
    const K = matmul2D(x, this.Wk);
    const V = matmul2D(x, this.Wv);

    const mask = causal ? makeCausalMask(seqLen) : undefined;

    // 헤드별 분리 → attention → concat
    const headOutputs: Value[][][] = [];
    for (let h = 0; h < this.numHeads; h++) {
      const start = h * dk;
      const end = start + dk;
      const Qh = Q.map(row => row.slice(start, end));
      const Kh = K.map(row => row.slice(start, end));
      const Vh = V.map(row => row.slice(start, end));
      headOutputs.push(scaledDotProductAttention(Qh, Kh, Vh, mask));
    }

    // concat heads: [seq, d_model]
    const concat = Array.from({ length: seqLen }, (_, i) =>
      headOutputs.flatMap(h => h[i])
    );

    // output projection
    return matmul2D(concat, this.Wo);
  }

  params(): Value[] {
    return [
      ...this.Wq.flat(),
      ...this.Wk.flat(),
      ...this.Wv.flat(),
      ...this.Wo.flat(),
    ];
  }
}

// ============================================================
// LayerNorm
// ============================================================

