  dFF?: number;
};

export class MiniGPT {
  tokenEmbed: Embedding;
  posEmbed: Value[][];    // [maxSeqLen, dModel]
  blocks: TransformerBlock[];
  lnFinal: LayerNorm;
  lmHead: Linear;

  constructor(public config: GPTConfig) {
    const { vocabSize, dModel, numHeads, numLayers, maxSeqLen } = config;
    const dFF = config.dFF ?? dModel * 4;

    this.tokenEmbed = new Embedding(vocabSize, dModel);

    // 위치 임베딩 (학습 가능)
    const scale = Math.sqrt(2 / dModel);
    this.posEmbed = Array.from({ length: maxSeqLen }, () =>
      Array.from({ length: dModel }, () =>
        Value.from((Math.random() * 2 - 1) * scale * 0.02)
      )
    );

    this.blocks = Array.from({ length: numLayers }, () =>
      new TransformerBlock(dModel, numHeads, dFF)
    );

    this.lnFinal = new LayerNorm(dModel);
    this.lmHead  = new Linear(dModel, vocabSize);
  }

  // ids: number[] → logits: [seq, vocabSize]
  forward(ids: number[]): Value[][] {
    const seqLen = ids.length;

    // Token + Position Embedding
    const tokEmb = this.tokenEmbed.forward(ids);
    let x: Value[][] = tokEmb.map((row, i) =>
      row.map((v, j) => v.add(this.posEmbed[i][j]))
    );

    // Transformer blocks
    for (const block of this.blocks) {
      x = block.forward(x);
    }

    // Final LN + LM Head
    const normed = x.map(row => this.lnFinal.forward(row));
    const logits = normed.map(row => this.lmHead.forward(row));

    return logits;
  }

  // 다음 토큰 예측 (greedy)
  predict(ids: number[], temperature = 1.0): number {
    const logits = this.forward(ids);
    const lastLogits = logits[logits.length - 1].map(v => v.data / temperature);
    return argmax(lastLogits);
  }

  // 텍스트 생성
  generate(seedIds: number[], maxNew: number, temperature = 1.0): number[] {
    let ids = [...seedIds];
    const maxLen = this.config.maxSeqLen;

    for (let i = 0; i < maxNew; i++) {
      const context = ids.slice(-maxLen);
      const logits = this.forward(context);
      const lastLogits = logits[logits.length - 1].map(v => v.data / temperature);

      const nextId = temperature === 0
        ? argmax(lastLogits)
        : sampleTopK(lastLogits, 5);
      ids.push(nextId);
    }
    return ids;
  }

  params(): Value[] {
    return [
      ...this.tokenEmbed.params(),
      ...this.posEmbed.flat(),
      ...this.blocks.flatMap(b => b.params()),
      ...this.lnFinal.params(),
      ...this.lmHead.params(),
    ];
  }
}

// ============================================================
// 학습 루프
// ============================================================

export type LMTrainConfig = {
  epochs: number;
  lr?: number;
  seqLen?: number;
  logEvery?: number;
  verbose?: boolean;
};

export function trainLM(
  model: MiniGPT,
  trainIds: number[],
  config: LMTrainConfig
): number[] {
  const { epochs, lr = 1e-3, seqLen = 16, logEvery = 10, verbose = true } = config;
  const optim = new Adam(lr);
  const losses: number[] = [];

  // 학습 시퀀스 생성
  const sequences: Array<{ input: number[]; target: number[] }> = [];
  for (let i = 0; i + seqLen < trainIds.length; i++) {
    sequences.push({
      input:  trainIds.slice(i, i + seqLen),
      target: trainIds.slice(i + 1, i + seqLen + 1),
    });
  }

  if (sequences.length === 0) {
    throw new Error(`학습 데이터 너무 짧음 (seqLen=${seqLen}보다 길어야 함)`);
  }

  for (let epoch = 0; epoch < epochs; epoch++) {
    // 랜덤 시퀀스 선택
    const seq = sequences[Math.floor(Math.random() * sequences.length)];
    const logits = model.forward(seq.input);

    // Cross-Entropy per position
    let totalLoss = Value.from(0);
    for (let t = 0; t < seq.target.length; t++) {
      totalLoss = totalLoss.add(softmaxCrossEntropy(logits[t], seq.target[t]));
    }
    const avgLoss = totalLoss.mul(Value.from(1 / seq.target.length));

    optim.zeroGrad(model.params());
    avgLoss.backward();
    // gradient clipping
    gradClip(model.params(), 1.0);
    optim.step(model.params());

    losses.push(avgLoss.data);

    if (verbose && (epoch + 1) % logEvery === 0) {
      console.log(`Epoch ${epoch + 1}/${epochs} — loss: ${avgLoss.data.toFixed(4)}`);
    }
  }

  return losses;
}

// ============================================================
// 헬퍼
// ============================================================

function argmax(arr: number[]): number {
  return arr.reduce((best, v, i) => v > arr[best] ? i : best, 0);
}

function sampleTopK(logits: number[], k: number): number {
  // Top-K 샘플링
  const indexed = logits.map((v, i) => ({ v, i })).sort((a, b) => b.v - a.v);
  const topK = indexed.slice(0, k);
  const maxV = Math.max(...topK.map(x => x.v));
  const exps = topK.map(x => Math.exp(x.v - maxV));
  const sum = exps.reduce((a, b) => a + b, 0);
  let r = Math.random() * sum;
  for (let i = 0; i < topK.length; i++) {
    r -= exps[i];
    if (r <= 0) return topK[i].i;
  }
  return topK[topK.length - 1].i;
}

function gradClip(params: Value[], maxNorm: number): void {
  const totalNorm = Math.sqrt(
    params.reduce((s, p) => s + p.grad * p.grad, 0)
  );
  if (totalNorm > maxNorm) {
    const scale = maxNorm / (totalNorm + 1e-6);
    for (const p of params) p.grad *= scale;
  }
}

