// FreeLang v8 ML — Phase 5 LLM 테스트
import { CharTokenizer, BPETokenizer, makeNgramData, padSequences } from '../src/ml/tokenizer';
import { MultiHeadAttention, LayerNorm, positionalEncoding, scaledDotProductAttention, makeCausalMask } from '../src/ml/attention';
import { MiniGPT, TransformerBlock, Embedding, FFN, trainLM } from '../src/ml/transformer';
import { Lexer } from '../src/lexer/lexer';
import { Parser } from '../src/parser/parser';
import { Interpreter } from '../src/runtime/interpreter';
import { Value } from '../src/ml/autodiff';

let passed = 0;
let failed = 0;

function test(name: string, fn: () => void) {
  try {
    fn();
    console.log(`  ✓ ${name}`);
    passed++;
  } catch (e: any) {
    console.log(`  ✗ ${name}: ${e.message}`);
    failed++;
  }
}

function assert(cond: boolean, msg: string) {
  if (!cond) throw new Error(msg);
}

function run(src: string) {
  const { tokens } = new Lexer(src).tokenize();
  const { program, errors } = new Parser(tokens).parse();
  if (errors.length > 0) throw new Error(`파서: ${errors[0].message}`);
  new Interpreter().run(program);
}

// ======================================================
// 1. CharTokenizer
// ======================================================
console.log('\n[1] CharTokenizer');

test('fit & vocabSize', () => {
  const tok = new CharTokenizer();
  tok.fit("hello world");
  // 특수 4개 + 고유 문자 수
  const uniq = new Set("hello world".split("")).size;
  assert(tok.vocabSize === 4 + uniq, `vocabSize: ${tok.vocabSize}`);
});

test('encode/decode 라운드트립', () => {
  const tok = new CharTokenizer();
  tok.fit("hello");
  const ids = tok.encode("hello");
  const decoded = tok.decode(ids);
  assert(decoded === "hello", `decoded: "${decoded}"`);
});

test('UNK 토큰 처리', () => {
  const tok = new CharTokenizer();
  tok.fit("abc");
  const ids = tok.encode("xyz");
  // UNK (id=1) 이어야 함
  assert(ids.every(id => id === 1), `ids: ${ids}`);
});

test('BOS/EOS 추가', () => {
  const tok = new CharTokenizer();
  tok.fit("hi");
  const ids = tok.encode("hi", true, true);
  assert(ids[0] === CharTokenizer.BOS, `BOS: ${ids[0]}`);
  assert(ids[ids.length - 1] === CharTokenizer.EOS, `EOS: ${ids[ids.length - 1]}`);
});

// ======================================================
// 2. BPE 토크나이저
// ======================================================
console.log('\n[2] BPE 토크나이저');

test('BPE fit', () => {
  const tok = new BPETokenizer();
  const text = "hello world hello hello world";
  tok.fit(text, 30);
  assert(tok.vocabSize >= 4, `vocabSize: ${tok.vocabSize}`);
});

test('BPE encode', () => {
  const tok = new BPETokenizer();
  tok.fit("hello world hello", 20);
  const ids = tok.encode("hello");
  assert(ids.length > 0, `encode 결과 없음`);
});

test('padSequences', () => {
  const seqs = [[1, 2, 3], [4, 5], [6, 7, 8, 9]];
  const padded = padSequences(seqs, 0, 4);
  assert(padded.every(s => s.length === 4), `길이 불일치`);
  assert(padded[1][2] === 0, `PAD: ${padded[1][2]}`);
});

test('makeNgramData', () => {
